"""Pak Studies XII PDF102 (spread): printed pp.193–194 — Ch.10 4 Pakistan–America; 5 Pakistan–Afghanistan (landscape photo coded as SVG)."""
from class12_book_common import Book, Builder

BOOK = Book('pak')
t = Builder()
P = t.p
H = t.h


def valley_svg(cap):
    """Coded flat illustration standing in for the uncaptioned photograph of an Afghan valley landscape with orchards below bare hills."""
    trees = ''.join(f'<circle cx="{x}" cy="{y}" r="{r}" fill="#3f7a3a"/>' for x, y, r in
                    [(40, 225, 16), (80, 232, 14), (130, 222, 18), (180, 235, 13), (230, 226, 17), (285, 233, 15), (335, 224, 18), (390, 234, 14), (440, 226, 16)])
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 300" role="img" aria-label="{cap}">'
            '<rect width="480" height="300" fill="#7ec3e8"/><ellipse cx="380" cy="50" rx="60" ry="14" fill="#ffffff" opacity="0.8"/>'
            '<polygon points="0,170 60,130 130,150 210,120 290,140 370,115 480,150 480,300 0,300" fill="#9a8c86"/>'
            '<polygon points="0,200 120,180 250,195 380,178 480,195 480,300 0,300" fill="#7ea05e"/>'
            f'{trees}<rect y="250" width="480" height="50" fill="#5e8a45"/>'
            f'<text x="240" y="285" text-anchor="middle" font-size="15" fill="#ffffff" font-family="sans-serif">{cap}</text></svg>')


H('4. Pakistan–America relations', '4۔ پاکستان-امریکہ تعلقات', '۴. د پاکستان او امریکا اړیکې')
P('From the very beginning it was Pakistan’s wish to establish friendly relations with all the countries of the world. Since Pakistan was weak economically, its effort therefore was to establish close friendly relations with countries rich in resources. Keeping these very principles in front, Pakistan extended the hand of friendship towards America. Although at the beginning America did not show much warmth, in 1949 the communist revolution in China compelled America to advance towards Pakistan.',
  'پاکستان کی شروع ہی سے یہ خواہش تھی کہ دُنیا کے تمام ممالک کے ساتھ دوستانہ تعلقات قائم کرے چونکہ پاکستان اقتصادی لحاظ سے کمزور تھا لہٰذا اُس کی کوشش تھی کہ وسائل سے مالا مال ممالک کے ساتھ قریبی دوستانہ تعلقات قائم کرے۔ انھی اصولوں کو سامنے رکھ کر پاکستان نے امریکہ کی طرف دوستی کا ہاتھ بڑھایا اگرچہ شروع میں امریکہ نے زیادہ گرم جوشی نہیں دکھائی تاہم 1949ء میں چین کے کیمونسٹ انقلاب نے امریکہ کو پاکستان کی طرف بڑھنے پر مجبور کر دیا۔',
  'پاکستان له پیله دا هیله درلوده چې د نړۍ له ټولو هېوادونو سره دوستانه اړیکې ټینګې کړي. څرنګه چې پاکستان اقتصادي پلوه کمزوری و، نو هڅه یې وه چې له سرچینو ډکو هېوادونو سره نږدې دوستانه اړیکې ټینګې کړي. د همدې اصولو په پام کې نیولو سره پاکستان امریکا ته د دوستۍ لاس اوږد کړ. که څه هم په پیل کې امریکا ډېره ګرم‌جوشي ونه ښوده، خو په ۱۹۴۹ز کې د چین کمونیستي انقلاب امریکا دې ته اړ کړه چې د پاکستان په لور وړاندې شي.')
P('The decade of 1950 holds great importance in the relations of Pakistan and America, because in this decade Pakistan joined the American bloc and also became a member of SEATO (SEATO) and CENTO (CENTO), formed under the shadow of America. Under these agreements America obtained the right to appoint secret spies on the soil of Pakistan, and thus made a cantonment of the air force at the place of Badaber near Peshawar.',
  '1950ء کی دہائی پاکستان اور امریکہ کے تعلقات میں بہت اہمیت رکھتی ہے کیونکہ اس دہائی میں پاکستان امریکی بلاک میں شامل ہو گیا اور امریکہ کے زیرِ سایہ بننے والی سیٹو (SEATO) اور سینٹو (CENTO) کا رکن بھی بن گیا۔ ان معاہدوں کی رُو سے امریکہ نے خفیہ جاسوسوں کی پاکستان کی سرزمین پر تقرری کا حق حاصل کر لیا اور یوں پشاور کے قریب بڈھ بیر کے مقام پر ایک ہوائی فوج کی چھاؤنی بنا دی۔',
  'د ۱۹۵۰ز لسیزه د پاکستان او امریکا په اړیکو کې ډېر اهمیت لري، ځکه په دې لسیزه کې پاکستان امریکايي بلاک کې شامل شو او د امریکا تر سیوري لاندې جوړ شوي سیټو (SEATO) او سنټو (CENTO) غړی هم شو. د دې تړونونو له مخې امریکا د پاکستان پر خاوره د پټو جاسوسانو د ګمارلو حق ترلاسه کړ، او په دې ډول یې د پېښور سره نږدې په بډه‌بېر کې د هوايي ځواک یوه چاوڼۍ جوړه کړه.')
P('Later a few events and the failure of expectations attached to America compelled President Ayub Khan to reconsider his foreign policy relating to America. President Ayub Khan not only ordered America to close its cantonments, but also adopted a policy of equality (Bilateralism) with both world powers (America and the Soviet Union). During the Pakistan–India wars of 1965 and 1971, America did not give any help to Pakistan, but stopped arms to Pakistan too. Since most of Pakistan’s weapons had been bought from America, the American ban therefore caused more harm to Pakistan’s armed forces.',
  'بعد میں چند واقعات اور امریکہ سے وابستہ توقعات میں ناکامی نے صدر ایوب خان کو اپنی امریکہ سے متعلق خارجہ پالیسی پر نظرِ ثانی کرنے پر مجبور کر دیا۔ صدر ایوب خان نے نہ صرف امریکہ کو اپنی چھاؤنیاں بند کرنے کا حکم دیا بلکہ دونوں عالمی طاقتوں (امریکہ اور سوویٹ یونین) سے برابری کی پالیسی (Bilateralism) بھی اپنائی۔ 1965ء اور 1971ء کی پاک بھارت جنگوں کے دوران امریکہ نے پاکستان کی کوئی مدد نہیں کی بلکہ پاکستان پر اسلحہ بھی بند کر دیا چونکہ پاکستان کا زیادہ تر اسلحہ امریکہ سے خریدا گیا تھا لہٰذا امریکی بندش نے پاکستان کی افواج کو زیادہ نقصان پہنچایا۔',
  'وروسته څو پېښو او له امریکا سره د تړلو تمو ناکامۍ ولسمشر ایوب خان دې ته اړ کړ چې د امریکا اړوند خپله بهرنۍ پالیسي له سره وګوري. ولسمشر ایوب خان نه یوازې امریکا ته د خپلو چاوڼیو د بندولو امر وکړ، بلکې له دواړو نړیوالو ځواکونو (امریکا او شوروي اتحاد) سره د برابرۍ پالیسي (Bilateralism) یې هم غوره کړه. د ۱۹۶۵ او ۱۹۷۱ز د پاک-هند جګړو پر مهال امریکا له پاکستان سره هېڅ مرسته ونه کړه، بلکې پر پاکستان یې وسله هم بنده کړه. څرنګه چې د پاکستان ډېره وسله له امریکا اخیستل شوې وه، نو امریکايي بندیز د پاکستان پوځونو ته ډېر زیان ورساوه.')
P('The Islamic revolution of Iran in 1979 and the intervention of communist forces in Afghanistan compelled America once again to pay attention towards Pakistan. The intervention of communist forces in Afghanistan was a danger to the security of Pakistan too. Therefore both countries, for the sake of their own interests, formed an alliance against the Soviet Union’s intervention in Afghanistan.',
  '1979ء کے اسلامی انقلابِ ایران اور کیمونسٹ فوجوں کی افغانستان میں مداخلت نے ایک دفعہ پھر امریکہ کو پاکستان کی طرف متوجہ ہونے پر مجبور کر دیا۔ افغانستان میں کیمونسٹ فوجوں کی مداخلت پاکستان کی سلامتی کے لیے بھی خطرہ تھی۔ لہٰذا دونوں ممالک نے اپنے اپنے مفادات کی خاطر سوویٹ یونین کی افغانستان میں مداخلت کے خلاف اتحاد کر لیا۔',
  'د ۱۹۷۹ز د ایران اسلامي انقلاب او په افغانستان کې د کمونیستي پوځونو مداخلې یو ځل بیا امریکا اړه کړه چې پاکستان ته پام وکړي. په افغانستان کې د کمونیستي پوځونو مداخله د پاکستان امنیت ته هم خطر و. نو دواړو هېوادونو د خپلو خپلو ګټو لپاره په افغانستان کې د شوروي اتحاد د مداخلې پر ضد اتحاد وکړ.')
P('In this new period of the twenty-first century Pakistan and America are once again moving forward on the paths of friendship. Although many analysts of Pakistan regard these relations even now as a temporary period, the officials of the American government have given several statements in which they have said again and again that this time America will maintain relations with Pakistan on permanent foundations. Whatever happens in the future, one thing is very clear, and we should all understand that in international relations there is neither any permanent friend nor any enemy. The thing that remains permanent is only national interests.',
  'اکیسویں صدی کے اس نئے دور میں پاکستان اور امریکہ ایک دفعہ پھر دوستی کی راہوں پر گامزن ہیں اگرچہ پاکستان کے بہت سارے تجزیہ نگار اب بھی ان تعلقات کو ایک عارضی دور سمجھتے ہیں لیکن امریکی حکومت کے عہدیداروں نے کئی بیانات دیے ہیں جن میں اُنھوں نے بار بار کہا ہے کہ اس دفعہ امریکہ پاکستان کے ساتھ مستقل بنیادوں پر تعلقات برقرار رکھے گا۔ مستقبل میں جو بھی ہوا ایک بات بڑی واضح ہے اور ہم سب کو سمجھنا چاہیے کہ بین الاقوامی تعلقات میں نہ تو کوئی مستقل دوست ہوتا ہے اور نہ ہی دشمن۔ مستقل رہنے والی چیز صرف قومی مفادات ہوتے ہیں۔',
  'د یوویشتمې پېړۍ په دې نوې دوره کې پاکستان او امریکا یو ځل بیا د دوستۍ پر لارو روان دي. که څه هم د پاکستان ډېر شنونکي اوس هم دا اړیکې یوه لنډمهاله دوره ګڼي، خو د امریکا د حکومت چارواکو څو بیانونه ورکړي چې پکې یې بیا بیا ویلي چې دا ځل به امریکا له پاکستان سره پر دایمي بنسټونو اړیکې ساتي. په راتلونکي کې چې هر څه وشي، یوه خبره ډېره روښانه ده او موږ ټول باید پوه شو چې په نړیوالو اړیکو کې نه دایمي دوست وي او نه دښمن؛ دایمي پاتې کېدونکی شی یوازې ملي ګټې دي.')
H('5. Pakistan–Afghanistan relations', '5۔ پاکستان افغانستان تعلقات', '۵. د پاکستان او افغانستان اړیکې')
P('Afghanistan is the second Islamic country in our neighbourhood, with which Pakistan is linked not only in religious but also in historical and cultural ties. However, despite all these ties, after the making of Pakistan relations with Afghanistan could not, from the beginning, be in a friendly atmosphere. Rather, Afghanistan was the only country which opposed Pakistan’s membership in the United Nations. However, Pakistan provided Afghanistan the facility of transit (Transit) for international trade.',
  'افغانستان ہمارے پڑوس میں دوسرا اسلامی ملک ہے جس کے ساتھ پاکستان نہ صرف مذہبی بلکہ تاریخی اور ثقافتی رشتوں میں بھی منسلک ہے۔ تاہم باوجود ان تمام رشتوں کے پاکستان بننے کے بعد افغانستان کے ساتھ تعلقات کی ابتداء دوستانہ ماحول میں نہ ہو سکی۔ بلکہ افغانستان وہ واحد ملک تھا جس نے اقوامِ متحدہ میں پاکستان کی ممبرشپ کی مخالفت کی۔ تاہم پاکستان نے افغانستان کو بین الاقوامی تجارت کے لیے راہ داری (Transit) کی سہولت فراہم کی۔',
  'افغانستان زموږ په ګاونډ کې دویم اسلامي هېواد دی، چې پاکستان ورسره نه یوازې په مذهبي، بلکې په تاریخي او کلتوري اړیکو کې هم تړلی دی. خو د دې ټولو اړیکو سره سره د پاکستان له جوړېدو وروسته له افغانستان سره د اړیکو پیل په دوستانه فضا کې ونه شو. بلکې افغانستان یوازینی هېواد و چې په ملګرو ملتونو کې یې د پاکستان د غړیتوب مخالفت وکړ. خو پاکستان افغانستان ته د نړیوالې سوداګرۍ لپاره د ترانزیټ (Transit) اسانتیا برابره کړه.')
t.visual('pak12-afghan-valley', valley_svg('A valley in Afghanistan'), valley_svg('افغانستان کی ایک وادی'), valley_svg('د افغانستان یوه دره'), 480 / 300)
P('In the relations of Pakistan and Afghanistan further complications arose in 1978 with the Afghan communist revolution, when the communist revolution came in Afghanistan (which was called the Saur Revolution (Saur Revolution)) and the Afghan people began an armed struggle against it. Then Pakistan, for the sake of Islamic spirit and national interest, gave enthusiastic support to the Afghan people, gave refuge in the country to lakhs of Afghan refugees and took care of them in every way.',
  'پاکستان اور افغانستان کے تعلقات میں 1978ء کے افغان کیمونسٹ انقلاب نے مزید پیچیدگیاں پیدا کیں جب افغانستان میں کیمونسٹ انقلاب (جسے ثور انقلاب Saur Revolution کہا گیا) آیا اور افغان عوام نے اس کے خلاف مسلح جد و جہد شروع کی تو پاکستان نے اسلامی جذبے اور ملکی مفاد کی خاطر افغان عوام کی پُر جوش حمایت کی۔ لاکھوں کی تعداد میں افغان مہاجرین کو ملک میں پناہ دی اور اُن کا ہر طرح سے خیال رکھا۔',
  'د پاکستان او افغانستان په اړیکو کې د ۱۹۷۸ز افغان کمونیستي انقلاب نورې پېچلتیاوې پیدا کړې. کله چې په افغانستان کې کمونیستي انقلاب (چې د ثور انقلاب Saur Revolution بلل شو) راغی او افغان خلکو د هغه پر ضد وسله‌واله مبارزه پیل کړه، نو پاکستان د اسلامي جذبې او ملي ګټې لپاره د افغان خلکو ګرم ملاتړ وکړ، په لکونو افغان کډوالو ته یې په هېواد کې پناه ورکړه او په هر ډول یې پاملرنه وکړه.')
P('In 1992, when the Afghan mujahideen established a government in Afghanistan, Pakistan was among those few countries which recognised the new government and established diplomatic relations with it. However, soon the Afghan mujahideen',
  '1992ء میں جب افغان مجاہدین نے افغانستان میں حکومت قائم کی تو پاکستان اُن چند ممالک میں سے تھا جنھوں نے نئی حکومت کو تسلیم کیا اور اُس کے ساتھ سفارتی تعلقات قائم کیے۔ تاہم جلد ہی افغان مجاہدین',
  'په ۱۹۹۲ز کې کله چې افغان مجاهدینو په افغانستان کې حکومت جوړ کړ، پاکستان په هغو څو هېوادونو کې و چې نوی حکومت یې په رسمیت وپېژانده او ورسره یې ډیپلوماتیکې اړیکې ټینګې کړې. خو ژر افغان مجاهدینو')
